'use strict';
const assert=require('node:assert/strict');
const fs=require('node:fs');
const path=require('node:path');
const root=path.resolve(__dirname,'../..');
const read=f=>fs.readFileSync(path.join(root,f),'utf8');
const mapper=read('docs/scifi-ui/scripts/formatx-apex-scene-stability.js');
const mesh=read('docs/scifi-ui/scripts/formatx-core-mesh3d-v10.js');
const fracture=read('docs/scifi-ui/scripts/formatx-core-fracture3d-v10.js');
const meshCss=read('docs/scifi-ui/styles/formatx-core-mesh3d.css');
const apex=read('docs/scifi-ui/scripts/formatx-apex-native.js');
const voice=read('docs/scifi-ui/scripts/organism-voice-stability.js');
const infinite=read('docs/scifi-ui/scripts/formatx-infinite-scroll.js');

assert.match(mapper,/fxApexSceneStability='ready-v18'/,'v10 production mapper missing');
assert.match(mapper,/formatx-core-mesh3d-v10\.js\?v=20260809-true-mesh3d-v10/,'v10 true mesh bootstrap missing');
assert.match(mapper,/formatx-core-fracture3d-v10\.js\?v=20260809-fracture3d-v10/,'v10 fracture bootstrap missing');
assert.match(mapper,/if\(uScene<\.92\)return vec2\(10\.,1\.\)/,'legacy SDF MAG suppression missing');
assert.match(mapper,/retired-for-real-3d-reactor/,'screen-space reactor retirement missing');
assert.match(mapper,/reference-narrow-fractured-true-mesh3d-v19/,'v10 visual marker missing');
assert.doesNotMatch(mapper,/scrollTo\s*\(|scrollIntoView\s*\(|preventDefault\s*\(/,'mapper must not capture scrolling');

assert.match(mesh,/getContext\('webgl2'/,'WebGL2 mesh context missing');
assert.match(mesh,/depth:true/,'mesh depth buffer missing');
assert.match(mesh,/gl\.enable\(gl\.DEPTH_TEST\)/,'mesh depth testing missing');
assert.match(mesh,/gl\.enable\(gl\.CULL_FACE\)/,'mesh face culling missing');
assert.match(mesh,/gl\.cullFace\(gl\.FRONT\)/,'back-face glass pass missing');
assert.match(mesh,/gl\.cullFace\(gl\.BACK\)/,'front-face glass pass missing');
assert.match(mesh,/gl\.bindBuffer\(gl\.ELEMENT_ARRAY_BUFFER/,'mesh index buffer missing');
assert.match(mesh,/gl\.drawElements\(gl\.TRIANGLES/,'indexed triangle rendering missing');
assert.match(mesh,/aPosition/,'vertex positions missing');
assert.match(mesh,/aNormal/,'vertex normals missing');
assert.match(mesh,/cross\(dFdx\(vP\),dFdy\(vP\)\)/,'faceted derivative normal missing');
assert.match(mesh,/uProjection\*uView\*vec4\(p,1\.\)/,'perspective projection missing');
assert.match(mesh,/xs=\.82/,'narrow horizontal proportion missing');
assert.match(mesh,/ys=1\.30/,'elongated vertical proportion missing');
assert.match(mesh,/dep=\.36/,'real Z depth missing');
assert.match(mesh,/core=up\(sphere\(\.060\)\)/,'compact real reactor sphere missing');
assert.match(mesh,/up\(torus\(\.23,\.0055\)\)/,'compact inner real reactor torus missing');
assert.match(mesh,/up\(torus\(\.34,\.005\)\)/,'compact middle real reactor torus missing');
assert.match(mesh,/up\(torus\(\.47,\.0046\)\)/,'compact outer real reactor torus missing');
assert.match(mesh,/hBeam=up\(box\(\.92,\.006,\.005\)\)/,'compact horizontal flare geometry missing');
assert.match(mesh,/vBeam=up\(box\(\.006,1\.05,\.005\)\)/,'compact vertical flare geometry missing');
assert.match(mesh,/tri\(crystal,0,\.46,pulse/,'violet back mesh pass missing');
assert.match(mesh,/tri\(crystal,0,\.51,pulse/,'cyan back mesh pass missing');
assert.match(mesh,/tri\(crystal,0,\.56,pulse/,'main glass mesh pass missing');
assert.match(mesh,/tri\(crystal,0,\.572,pulse/,'outer spectral shell missing');
assert.match(mesh,/fxCoreMesh3d='ready-v10'/,'v10 mesh ready marker missing');
assert.match(mesh,/fxCoreGeometry='indexed-triangle-mesh-v10'/,'v10 indexed mesh marker missing');
assert.match(mesh,/fxCoreProportion='x0\.82-y1\.30'/,'v10 proportion marker missing');
assert.match(mesh,/fxCoreReactorGeometry='compact-sphere-plus-3-tori-plus-2-box-beams'/,'compact real reactor geometry marker missing');
assert.doesNotMatch(mesh,/drawImage\s*\(|new Image\s*\(|background-image/i,'MAG must not be image-backed');
assert.doesNotMatch(mesh,/THREE\b|three\.js|gsap/i,'third-party scene framework forbidden');

assert.match(fracture,/getContext\('webgl2'/,'fracture WebGL2 context missing');
assert.match(fracture,/gl\.bindBuffer\(gl\.ELEMENT_ARRAY_BUFFER/,'fracture index buffer missing');
assert.match(fracture,/gl\.drawElements\(gl\.LINES/,'fracture must use indexed GL_LINES');
assert.match(fracture,/xs=\.82/,'fracture X proportion must match mesh');
assert.match(fracture,/ys=1\.30/,'fracture Y proportion must match mesh');
assert.match(fracture,/depth=\.36/,'fracture Z surface must match mesh');
assert.match(fracture,/fxCoreFracture3d='ready-v10'/,'fracture ready marker missing');
assert.match(fracture,/fxCoreFractureGeometry='indexed-gl-lines-v10'/,'fracture geometry marker missing');
assert.match(fracture,/fxCoreFractureAlignment='x0\.82-y1\.30'/,'fracture alignment marker missing');
assert.doesNotMatch(fracture,/drawImage\s*\(|new Image\s*\(|background-image/i,'fracture network must not be image-backed');

assert.match(meshCss,/pointer-events: none/,'mesh must not capture input');
assert.match(meshCss,/height: 100dvh/,'dynamic viewport missing');
assert.match(apex,/quality: coarse\.matches \? 0\.82 : 0\.88/,'Apex background quality regressed');
assert.match(voice,/window\.visualViewport/,'dialogue viewport guard missing');
assert.match(voice,/keyboardInset/,'keyboard inset guard missing');
assert.match(infinite,/const VERSION = 'seamless-v7'/,'seamless-v7 regressed');
assert.match(infinite,/root\.dataset\.fxInfiniteInput = 'native'/,'native momentum regressed');
console.log('PASS: v10 MAG uses a narrower/taller real indexed WebGL2 crystal, compact geometric reactor and aligned high-contrast indexed 3D fracture network.');
